<?php
namespace App\Jobs;use App\Domain\Workflow\StepExecutionStatus;use App\Models\StepExecution;use App\Services\WorkflowQueue;use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Illuminate\Queue\{InteractsWithQueue,SerializesModels};use Illuminate\Support\Facades\DB;
final class ReleaseRetryStep implements ShouldQueue{use Dispatchable,InteractsWithQueue,Queueable,SerializesModels;public function __construct(public string $stepId){}public function handle(WorkflowQueue $queues):void{$execution=DB::transaction(function(){$s=StepExecution::with('execution.version.workflow')->lockForUpdate()->findOrFail($this->stepId);if($s->status!==StepExecutionStatus::RetryWait||($s->retry_at&&$s->retry_at->isFuture()))return null;$s->update(['status'=>StepExecutionStatus::Pending,'retry_at'=>null]);return $s->execution;},3);if($execution)ExecuteWorkflowStep::dispatch($execution->id)->onQueue($queues->name($execution->version->workflow));}}
